                memory: "512Mi",
            },
            requests: {
                cpu: "250m",
                memory: "256Mi",
            },
        },
    },
    runProperties: {
        timeout: "<+input>.default('60s')",
        interval: "<+input>.default('15s')",
    },
    variables: [
        {
