```typescript
import * as pulumi from "@pulumi/pulumi";
import * as harness from "@pulumi/harness";

// Example 1: Cluster Generator
const clusterGenerator = new harness.platform.GitopsApplicationset("cluster_generator", {
    orgId: "default",
    projectId: "projectId",
    agentId: "account.agentuseast1",
    upsert: true,
    applicationset: {
        metadata: {
            name: "cluster-appset",
            namespace: "argocd",
        },
        spec: {
            goTemplate: true,
            goTemplateOptions: ["missingkey=error"],
            generators: [{
                clusters: [{
                    enabled: true,
                }],
            }],
            template: {
                metadata: {
                    name: "{{.name}}-guestbook",
                    labels: {
                        env: "dev",
                    },
                },
                spec: {
                    project: "default",
                    source: {
                        repoUrl: "https://github.com/argoproj/argocd-example-apps.git",
                        path: "helm-guestbook",
                        targetRevision: "HEAD",
                    },
                    destination: {
                        server: "{{.url}}",
                        namespace: "app-ns-{{.name}}",
                    },
                },
            },
        },
    },
});
// Example 2: List Generator
const listGenerator = new harness.platform.GitopsApplicationset("list_generator", {
    orgId: "default",
    projectId: "projectId",
    agentId: "account.agentuseast1",
    upsert: true,
    applicationset: {
        metadata: {
            name: "list-appset",
        },
        spec: {
            goTemplate: true,
            goTemplateOptions: ["missingkey=error"],
            generators: [{
                lists: [{
                    elements: [
                        {
                            cluster: "engineering-dev",
                            url: "https://kubernetes.default.svc",
                        },
                        {
                            cluster: "engineering-prod",
                            url: "https://kubernetes.prod.svc",
                        },
                    ],
                }],
            }],
            template: {
                metadata: {
                    name: "{{.cluster}}-guestbook",
                },
                spec: {
                    project: "default",
                    source: {
                        repoUrl: "https://github.com/argoproj/argocd-example-apps.git",
                        path: "helm-guestbook",
                        targetRevision: "HEAD",
                    },
                    destination: {
                        server: "{{.url}}",
                        namespace: "default",
                    },
                },
            },
        },
    },
});
// Example 3: Git Generator with Files
const gitFiles = new harness.platform.GitopsApplicationset("git_files", {
    orgId: "default",
    projectId: "projectId",
    agentId: "account.agentuseast1",
    upsert: true,
    applicationset: {
        metadata: {
            name: "git-files-appset",
        },
        spec: {
            generators: [{
                gits: [{
                    repoUrl: "https://github.com/example/config-repo",
                    revision: "main",
                    files: [{
                        path: "apps/*/config.json",
                    }],
                }],
            }],
            template: {
                metadata: {
                    name: "{{.path.basename}}-app",
                },
                spec: {
                    project: "default",
                    source: {
                        repoUrl: "https://github.com/example/app-repo",
                        path: "{{.path.path}}",
                        targetRevision: "main",
                    },
                    destination: {
                        server: "https://kubernetes.default.svc",
                        namespace: "{{.path.basename}}",
                    },
                },
            },
        },
    },
});
// Example 4: Git Generator with Directories
const gitDirectories = new harness.platform.GitopsApplicationset("git_directories", {
    orgId: "default",
    projectId: "projectId",
    agentId: "account.agentuseast1",
    upsert: true,
    applicationset: {
        metadata: {
            name: "git-directories-appset",
        },
        spec: {
            generators: [{
                gits: [{
                    repoUrl: "https://github.com/argoproj/argo-cd.git",
                    revision: "HEAD",
                    directories: [{
                        path: "applicationset/examples/git-generator-directory/cluster-addons/*",
                        exclude: false,
                    }],
                }],
            }],
            template: {
                metadata: {
                    name: "{{.path.basename}}-addon",
                },
                spec: {
                    project: "default",
                    source: {
                        repoUrl: "https://github.com/argoproj/argo-cd.git",
                        path: "{{.path.path}}",
                        targetRevision: "HEAD",
                    },
                    destination: {
                        server: "https://kubernetes.default.svc",
                        namespace: "{{.path.basename}}",
                    },
                    syncPolicy: {
                        automated: {
                            prune: true,
                            selfHeal: true,
                        },
                    },
                },
            },
        },
    },
});
