resources:
  # Account-scoped DELETE rule — keep last 10 versions, runs nightly
  nightlyCleanup:
    type: harness:platform:HarLifecycleRule
    name: nightly_cleanup
    properties:
      accountId: your-account-id
      name: nightly-cleanup
      action: DELETE
      description: Keep last 10 versions of all artifacts
      applyTo:
        mode: ALL_IN_SCOPE
      criteria:
        match: ALL
        rules:
          - type: KEEP_LAST_N
            value: 10
      schedule:
        expression: 0 2 * * *
        timezone: UTC
  # Project-scoped DELETE rule — delete artifacts older than 30 days
  ageBasedCleanup:
    type: harness:platform:HarLifecycleRule
    name: age_based_cleanup
    properties:
      accountId: your-account-id
      orgId: your-org-id
      projectId: your-project-id
      name: age-based-cleanup
      action: DELETE
      applyTo:
        mode: ALL_IN_SCOPE
      criteria:
        match: ALL
        rules:
          - type: AGE_BASED
            value: 30
            unit: DAYS
  # Org-scoped PROTECT rule — protect images in specific registries matching a tag pattern
  protectProd:
    type: harness:platform:HarLifecycleRule
    name: protect_prod
    properties:
      accountId: your-account-id
      orgId: your-org-id
      name: protect-prod-images
      action: PROTECT
      packageType: DOCKER
      applyTo:
        mode: EXPLICIT
        registries:
          - prod-registry
          - release-registry
      filterConfig:
        packageType: DOCKER
        tagNameAllowedPatterns:
          - v*
          - release-*
  # Account-scoped DELETE rule with multiple criteria (ANY match)
